const Controlls = () => {
  const heights = [20, 40, 180, 77];
  const createItem = (i: number) => ({
    index: i,
    height: heights[i % 4],
  });

  const [data, setData] = createSignal(
    Array.from({ length: 1000 }).map((_, i) => createItem(i)),
  );

  const [scrollOffset, setScrollOffset] = createSignal(0);
  const [scrolling, setScrolling] = createSignal(false);
  const [scrollTarget, setScrollTarget] = createSignal(567);
  const [prepend, setPrepend] = createSignal(false);

  let handle: VListHandle | undefined;

  return (
    <div
      style={{ height: "100%", display: "flex", "flex-direction": "column" }}
    >
      <div>offset: {scrollOffset()}</div>
      <div>scrolling: {String(scrolling())}</div>
      <div>
        <input
          type="number"
          value={scrollTarget()}
          onInput={(e) => {
            setScrollTarget(Number((e.target as HTMLInputElement).value));
          }}
        />
        <button
          onClick={() => {
            handle?.scrollToIndex(scrollTarget());
          }}
        >
          scrollToIndex
        </button>
      </div>
      <div>
        <button
          onClick={() => {
            setData((prev) => {
              const items = Array.from({ length: 100 }).map((_, i) =>
                createItem(i + prev.length),
              );
              return prepend() ? [...items, ...prev] : [...prev, ...items];
            });
          }}
        >
          append
        </button>
        <label>
          <input
            type="checkbox"
            checked={prepend()}
            onchange={() => {
              setPrepend((prev) => !prev);
            }}
          />
          prepend
        </label>
        <button
          onclick={() => {
            setData((prev) => {
              const items = [...prev];
              items.pop();
              return items;
            });
          }}
        >
          pop
        </button>
      </div>
      <VList
        ref={handle}
        data={data()}
        shift={prepend()}
        style={{ height: "100vh" }}
        onScroll={(offset) => {
          setScrollOffset(offset);
          setScrolling(true);
        }}
        onScrollEnd={() => {
          setScrolling(false);
        }}
      >
        {(d) => (
          <div
            style={{
              height: d.height + "px",
              "border-bottom": "solid 1px #ccc",
              background: "#fff",
            }}
          >
            {d.index}
          </div>
        )}
      </VList>
    </div>
  );
};

