const ScrollTo = () => {
  const LENGTH = 1000;
  const [rowIndex, setRowIndex] = createSignal(567);
  const [colIndex, setColIndex] = createSignal(567);
  const [vertical, setVertical] = createSignal(1000);
  const [horizontal, setHorizontal] = createSignal(1000);
  let handle: VGridHandle | undefined;
  return (
    <div
      style={{ height: "100vh", display: "flex", "flex-direction": "column" }}
    >
      <div>
        <label>
          col
          <input
            type="number"
            value={colIndex()}
            onInput={(e) => setColIndex(Number(e.currentTarget.value))}
          />
        </label>
        <label>
          row
          <input
            type="number"
            value={rowIndex()}
            onInput={(e) => setRowIndex(Number(e.currentTarget.value))}
          />
        </label>
        <button
          onClick={() => {
            handle?.scrollToIndex({
              rowIndex: rowIndex(),
              colIndex: colIndex(),
            });
          }}
        >
          scroll to index
        </button>
        <button
          onClick={() => {
            setColIndex(Math.floor(LENGTH * Math.random()));
            setRowIndex(Math.floor(LENGTH * Math.random()));
          }}
        >
          randomize
        </button>
      </div>
      <div>
        <label>
          x
          <input
            type="number"
            value={horizontal()}
            onInput={(e) => setHorizontal(Number(e.currentTarget.value))}
          />
        </label>
        <label>
          y
          <input
            type="number"
            value={vertical()}
            onInput={(e) => setVertical(Number(e.currentTarget.value))}
          />
        </label>
        <button
          onClick={() => {
            handle?.scrollTo({
              vertical: vertical(),
              horizontal: horizontal(),
            });
          }}
        >
          scroll to offset
        </button>
        <button
          onClick={() => {
            handle?.scrollBy({
              vertical: vertical(),
              horizontal: horizontal(),
            });
          }}
        >
          scroll by offset
        </button>
      </div>
      <VGrid
        ref={handle}
        rows={LENGTH}
        rowHeight={80}
        cols={LENGTH}
        colWidth={160}
        style={{
          flex: 1,
          "box-sizing": "border-box",
          border: "solid 1px gray",
          background: "white",
        }}
      >
        {(rowIndex, colIndex) => (
          <div
            style={{
              padding: "4px",
              "border-right": "solid 1px gray",
              "border-bottom": "solid 1px gray",
            }}
          >
            {rowIndex} / {colIndex}
          </div>
        )}
      </VGrid>
    </div>
  );
};

const Default = () => {
  let id = 0;
  const createItem = ({
    value = faker.lorem.paragraphs(1),
    me,
  }: { value?: string; me?: boolean } = {}): Data => ({
    id: id++,
    value,
    me,
  });
  const [items, setItems] = createSignal<Data[]>(
    Array.from({ length: 100 }, () => createItem()),
  );
  let virtualizerHandle: VirtualizerHandle | undefined;
  const [isPrepend, setIsPrepend] = createSignal(false);
  const [shouldStickToBottom, setShouldStickToBottom] = createSignal(true);
  const [value, setValue] = createSignal("Hello world!");
  const [fetching, setFetching] = createSignal(false);

  createEffect(() => {
    items();
    setIsPrepend(false);
  });

  createEffect(() => {
    const lastItemIndex = items().length - 1;
    if (shouldStickToBottom()) {
      virtualizerHandle?.scrollToIndex(lastItemIndex, { align: "end" });
    }
  });

  onMount(() => {
    let canceled = false;
    let timer: ReturnType<typeof setTimeout> | null = null;
    const setTimer = () => {
      timer = setTimeout(() => {
        if (canceled) return;
        setItems((prev) => [...prev, createItem()]);
        setTimer();
      }, 5000);
    };
    setTimer();
    onCleanup(() => {
      canceled = true;
      if (timer) clearTimeout(timer);
    });
  });

  const disabled = () => !value().length;
  const submit = () => {
    if (disabled()) return;
    setShouldStickToBottom(true);
    setItems((prev) => [...prev, createItem({ value: value(), me: true })]);
    setValue("");
  };

  return (
    <div
      style={{
        width: "100vw",
        height: "100vh",
        display: "flex",
        "flex-direction": "column",
      }}
    >
      <div
        style={{
          "overflow-y": "auto",
          flex: 1,
          // opt out browser's scroll anchoring on header/footer because it will conflict to scroll anchoring of virtualizer
          "overflow-anchor": "none",
          // flex style for spacer
          display: "flex",
          "flex-direction": "column",
        }}
      >
        <div
          style={{
            // spacer to align virtualizer to the bottom when all items are visible in the viewport
            "flex-grow": 1,
          }}
        />
        <Spinner visible={fetching()} />
        <Virtualizer
          ref={virtualizerHandle}
          data={items()}
          shift={isPrepend()}
          startMargin={spinnerHeight}
          onScroll={async (offset) => {
            const handle = virtualizerHandle;
            if (!handle) return;
            setShouldStickToBottom(
              offset -
                spinnerHeight -
                handle.scrollSize +
                handle.viewportSize >=
                -1.5,
            );
            if (offset < spinnerHeight + 100 && !fetching()) {
              setFetching(true);
              await new Promise((resolve) => setTimeout(resolve, 1000));
              setIsPrepend(true);
              setItems((prev) => [
                ...Array.from({ length: 100 }, () => createItem()),
                ...prev,
              ]);
              setFetching(false);
            }
          }}
        >
          {(d) => <Item me={d.me}>{d.value}</Item>}
        </Virtualizer>
      </div>
      <form
        style={{
          display: "flex",
          "flex-direction": "column",
          margin: "10px",
        }}
        onSubmit={(e) => {
          e.preventDefault();
          e.stopPropagation();
          submit();
        }}
      >
        <textarea
          style={{ flex: 1 }}
          rows={6}
          value={value()}
          onInput={(e) => setValue(e.currentTarget.value)}
          onKeyDown={(e) => {
            if (e.code === "Enter" && (e.ctrlKey || e.metaKey)) {
              submit();
              e.preventDefault();
            }
          }}
        />
        <div
          style={{
            display: "flex",
            "flex-direction": "row",
            gap: "8px",
            "justify-content": "flex-end",
          }}
        >
          <button type="submit" disabled={disabled()}>
            submit
          </button>
        </div>
      </form>
    </div>
  );
};

const Default = () => {
  let ref: VListHandle | undefined;
  const [activeIndex, setActiveIndex] = createSignal(0);
  const [items] = createSignal(
    Array.from({ length: 1000 }).map((_, id) => ({ id })),
  );
  return (
    <StickyIndexContext.Provider value={[activeIndex, setActiveIndex]}>
      <VList
        ref={ref}
        data={items()}
        item={StickyItem}
        keepMounted={[activeIndex()]}
        onScroll={() => {
          if (!ref) return;
          const start = ref.findItemIndex(ref.scrollOffset);
          const activeStickyIndex = [...stickyIndexes]
            .reverse()
            .find((index) => start >= index)!;
          setActiveIndex(activeStickyIndex);
        }}
      >
        {(data, index) => {
          const isSticky = () => stickyIndexes.has(index());
          return (
            <div
              style={{
                height: (isSticky() ? stickyItemHeight : 80) + "px",
                "border-bottom": "solid 1px #ccc",
                background: isSticky() ? "#B8C1C8" : "#fff",
                color: isSticky() ? "#fff" : undefined,
                "padding-right": "4px",
                "padding-left": "4px",
              }}
            >
              {data.id}
            </div>
          );
        }}
      </VList>
    </StickyIndexContext.Provider>
  );
};
